def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    truck_patches = image_patch.find("truck")
    other_truck_patches = image_patch.find("other truck")

    if not truck_patches or not other_truck_patches:
        return image_patch

    truck_depths = [t.compute_depth() for t in truck_patches]
    other_truck_depths = [ot.compute_depth() for ot in other_truck_patches]

    for i, td in enumerate(truck_depths):
        if td < min(other_truck_depths):
